solution.code:
// Mini generator blog: meniru getStaticPaths + routing berbasis file Astro.

function segmenDariFile(file) {
  const tanpaEkstensi = file.replace(/\.(astro|md)$/, "");
  const segmen = tanpaEkstensi.split("/");
  if (segmen[segmen.length - 1] === "index") segmen.pop();
  return segmen;
}

function jenisSegmen(s) {
  if (/^\[\.\.\.[^\]]+\]$/.test(s)) return 2; // [...x]
  if (/^\[[^\]]+\]$/.test(s)) return 1; // [x]
  return 0; // statis
}

function namaParam(s) {
  return s.replace(/^\[(\.\.\.)?/, "").replace(/\]$/, "");
}

function bandingPrioritas(a, b) {
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const ja = i < a.length ? jenisSegmen(a[i]) : -1;
    const jb = i < b.length ? jenisSegmen(b[i]) : -1;
    if (ja !== jb) return ja - jb;
  }
  return 0;
}

function bangunSitus({ pages, posts }) {
  const terbit = posts
    .filter((p) => !p.data.draft)
    .slice()
    .sort((a, b) => (a.data.tanggal < b.data.tanggal ? 1 : a.data.tanggal > b.data.tanggal ? -1 : a.id < b.id ? -1 : 1));

  const daftarTag = [...new Set(terbit.flatMap((p) => p.data.tag))].sort();

  const halamanFile = pages.filter((f) => /\.(astro|md)$/.test(f) && !f.split("/").some((s) => s.startsWith("_")));

  const calon = [];
  halamanFile.forEach((file, urutan) => {
    const segmen = segmenDariFile(file);
    const dinamis = segmen.find((s) => jenisSegmen(s) > 0);
    const isi = [];
    if (!dinamis) {
      isi.push({ ganti: null, props: {} });
    } else if (namaParam(dinamis) === "slug") {
      for (const p of terbit) isi.push({ ganti: p.id, props: { judul: p.data.judul, tanggal: p.data.tanggal } });
    } else if (namaParam(dinamis) === "tag") {
      for (const t of daftarTag) isi.push({ ganti: t, props: { tag: t, posts: terbit.filter((p) => p.data.tag.includes(t)).map((p) => p.id) } });
    }
    for (const { ganti, props } of isi) {
      const bagian = segmen.map((s) => (jenisSegmen(s) > 0 ? ganti : s));
      calon.push({ url: "/" + bagian.join("/"), file, props, segmen, urutan });
    }
  });

  const pemenang = new Map();
  for (const c of calon) {
    const lama = pemenang.get(c.url);
    if (!lama || bandingPrioritas(c.segmen, lama.segmen) < 0) pemenang.set(c.url, c);
  }
  const halaman = calon
    .filter((c) => pemenang.get(c.url) === c)
    .map(({ url, file, props }) => ({ url, file, props }));

  function resolve(path) {
    let bersih = path.split("?")[0].split("#")[0];
    if (bersih.length > 1) bersih = bersih.replace(/\/+$/, "");
    if (bersih === "") bersih = "/";
    const h = halaman.find((x) => x.url === bersih);
    if (h) return { status: 200, file: h.file, props: h.props };
    const galat = halaman.find((x) => x.file === "404.astro");
    return { status: 404, file: galat ? galat.file : null, props: {} };
  }

  return { halaman, resolve };
}

