function isiSlot(template, slots) {
  const pola = /<slot(?:\s+name="([^"]+)")?\s*(?:\/>|>([\s\S]*?)<\/slot>)/g;
  return template.replace(pola, (_, nama, cadangan) => {
    const isi = slots[nama || "default"];
    if (isi !== undefined) return isi;
    return cadangan !== undefined ? cadangan : "";
  });
}

