function keSegmen(file) {
  const s = file.replace(/\.(astro|md)$/, "").split("/");
  if (s[s.length - 1] === "index") s.pop();
  return s;
}

function cocok(seg, url) {
  const params = {};
  for (let i = 0; i < seg.length; i++) {
    const s = seg[i];
    if (s.startsWith("[...")) {
      if (i !== seg.length - 1 || url.length <= i) return null;
      params[s.slice(4, -1)] = url.slice(i).join("/");
      return params;
    }
    if (i >= url.length) return null;
    if (s.startsWith("[")) params[s.slice(1, -1)] = url[i];
    else if (s !== url[i]) return null;
  }
  return seg.length === url.length ? params : null;
}

function skor(seg) {
  let n = 0;
  for (const s of seg) n += s.startsWith("[...") ? 100 : s.startsWith("[") ? 1 : 0;
  return n;
}

function cocokkanRoute(files, path) {
  const url = path.split("/").filter(Boolean);
  let terbaik = null;
  for (const file of files) {
    const seg = keSegmen(file);
    const params = cocok(seg, url);
    if (!params) continue;
    if (!terbaik || skor(seg) < terbaik.skor) terbaik = { file, params, skor: skor(seg) };
  }
  return terbaik ? { file: terbaik.file, params: terbaik.params } : null;
}

