function classList(...nilai) {
  const hasil = [];
  function tambah(v) {
    if (!v) return;
    if (typeof v === "string") {
      for (const kata of v.split(/\s+/)) if (kata && !hasil.includes(kata)) hasil.push(kata);
    } else if (Array.isArray(v)) {
      for (const x of v) tambah(x);
    } else if (typeof v === "object") {
      for (const k of Object.keys(v)) if (v[k]) tambah(k);
    }
  }
  for (const v of nilai) tambah(v);
  return hasil.join(" ");
}

