function validasiPost(data) {
  const errors = [];
  if (typeof data.judul !== "string" || data.judul.length === 0) errors.push("judul");
  if (typeof data.tanggal !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(data.tanggal)) errors.push("tanggal");
