const KELOMPOK = {
  "client:load": "segera",
  "client:only": "segera",
  "client:idle": "senggang",
  "client:visible": "terlihat",
  "client:media": "media",
  "server:defer": "server",
};

function rencanaHidrasi(komponen) {
  const hasil = { statis: [], segera: [], senggang: [], terlihat: [], media: [], server: [] };
  for (const k of komponen) {
    if (!k.direktif) {
      hasil.statis.push(k.nama);
      continue;
    }
    const kunci = KELOMPOK[k.direktif];
    if (!kunci) throw new Error("Direktif tidak dikenal: " + k.direktif);
    if (k.direktif === "client:media" && !k.nilai) {
      throw new Error("client:media butuh media query");
    }
    hasil[kunci].push(k.nama);
  }
  return hasil;
}

