solution.code:
async function jalankanMiddleware(daftar, context) {
  async function jalankan(i) {
    if (i >= daftar.length) return context.render();
    let hasilNext;
    const next = () => {
      hasilNext = jalankan(i + 1);
      return hasilNext;
    };
    const nilai = await daftar[i](context, next);
    if (nilai !== undefined) return nilai;
    if (hasilNext) return hasilNext;
    throw new Error("Middleware harus mengembalikan respons atau memanggil next()");
  }
  return jalankan(0);
}

