solution.code:
function bersihkanPath(path) {
  let p = path.split("?")[0].split("#")[0];
  if (p.length > 1) p = p.replace(/\/+$/, "");
  return p || "/";
}

function metaHalaman(halaman, situs) {
  const dasar = situs.url.replace(/\/+$/, "");
  const kanonis = dasar + bersihkanPath(halaman.path);
  const g = halaman.gambar || situs.gambar;
  const gambar = g.startsWith("http") ? g : dasar + (g.startsWith("/") ? g : "/" + g);
  const judul = halaman.judul || situs.nama;
  const tags = [{ tag: "title", isi: halaman.judul ? halaman.judul + " | " + situs.nama : situs.nama }];
  if (halaman.deskripsi) tags.push({ tag: "meta", name: "description", content: halaman.deskripsi });
  tags.push({ tag: "link", rel: "canonical", href: kanonis });
  tags.push({ tag: "meta", property: "og:title", content: judul });
  if (halaman.deskripsi) tags.push({ tag: "meta", property: "og:description", content: halaman.deskripsi });
  tags.push({ tag: "meta", property: "og:url", content: kanonis });
  tags.push({ tag: "meta", property: "og:image", content: gambar });
  return tags;
}

