solution.code:
const ADAPTER = { vercel: "@astrojs/vercel", netlify: "@astrojs/netlify" };

function pilihDeploy(kebutuhan) {
  const { halamanDinamis = 0, totalHalaman = 0, platform } = kebutuhan || {};
  if (halamanDinamis === 0) return { output: "static", adapter: null };
  if (platform === "github-pages") {
    throw new Error("GitHub Pages hanya untuk situs statis");
  }
  const adapter = ADAPTER[platform] || "@astrojs/node";
  const output = halamanDinamis * 2 > totalHalaman ? "server" : "static";
  return { output, adapter };
}

